// 24-S7 acceptance: the session panel's words. Join and leave notes come
// from changes to the present set: the first answer is the baseline ("You
// joined. Adam is here."), an account appearing joined, one gone for 5 s
// left (a reload in between makes none). Another builder's Enter Hints and
// Start Over are noted. Times are 24-hour HH:MM, days "Nov 8, 2026". Pure.
// Do not edit this file to match an implementation.
import { describe, expect, it } from 'vitest';
import {
  LEAVE_GRACE_MS, PresenceNotes, builderName, formatNoteDay, formatNoteTime, operationNote,
} from './session';
import type { Operation } from './operation';

const adam = { userId: 'adam', username: 'Adam' };
const jay = { userId: 'jay', username: 'Jay' };
const kim = { userId: 'kim', username: 'Kim' };
const lee = { userId: 'lee', username: 'Lee' };

describe('24-S7-3 join and leave notes', () => {
  it('the first answer is the baseline: who is here, or nothing when alone', () => {
    expect(new PresenceNotes().update([adam], 0)).toEqual(['You joined. Adam is here.']);
    expect(new PresenceNotes().update([adam, kim], 0)).toEqual(['You joined. Adam and Kim are here.']);
    expect(new PresenceNotes().update([adam, kim, lee], 0)).toEqual(['You joined. Adam, Kim and Lee are here.']);
    const alone = new PresenceNotes();
    expect(alone.update([], 0)).toEqual([]);
    expect(alone.update([], 1000)).toEqual([]);
    expect(alone.update([jay], 2000)).toEqual(['Jay joined the session.']);
  });

  it('a join is noted at once; a leave once the account has been gone for the grace', () => {
    const notes = new PresenceNotes();
    notes.update([], 0);
    expect(notes.update([jay], 1000)).toEqual(['Jay joined the session.']);
    expect(notes.update([jay], 2000)).toEqual([]);
    expect(notes.update([], 3000)).toEqual([]);
    expect(notes.update([], 3000 + LEAVE_GRACE_MS - 1)).toEqual([]);
    expect(notes.update([], 3000 + LEAVE_GRACE_MS)).toEqual(['Jay left the session.']);
    expect(notes.update([], 3000 + LEAVE_GRACE_MS + 1000)).toEqual([]);
    expect(notes.update([jay], 20_000)).toEqual(['Jay joined the session.']);
  });

  it('a reload (gone, then back within the grace) makes no notes', () => {
    const notes = new PresenceNotes();
    notes.update([jay, kim], 0);
    expect(notes.update([kim], 1000)).toEqual([]);
    expect(notes.update([jay, kim], 2000)).toEqual([]);
    expect(notes.update([jay, kim], 1000 + LEAVE_GRACE_MS + 1000)).toEqual([]);
  });

  it('several changes at once are each noted', () => {
    const notes = new PresenceNotes();
    notes.update([jay], 0);
    expect(notes.update([kim, lee], 1000)).toEqual(['Kim joined the session.', 'Lee joined the session.']);
    expect(notes.update([kim, lee], 1000 + LEAVE_GRACE_MS)).toEqual(['Jay left the session.']);
  });

  it('a missing username reads "A builder"', () => {
    expect(builderName(null)).toBe('A builder');
    expect(builderName('  ')).toBe('A builder');
    expect(builderName('Jay')).toBe('Jay');
    expect(new PresenceNotes().update([{ userId: 'x', username: null }], 0)).toEqual(['You joined. A builder is here.']);
  });
});

describe('24-S7-3 notes for another builder’s Enter Hints and Start Over', () => {
  const envelope = { opId: 'o', puzzleId: 'p', clientId: 'c', epoch: 0, baseVersion: 0 };
  it('names the builder; other kinds make no note', () => {
    expect(operationNote({ ...envelope, kind: 'enterHints' } as Operation, jay)).toBe('Jay moved the puzzle to Create Hints.');
    expect(operationNote({ ...envelope, kind: 'startOver', keepLockedWords: false } as Operation, adam)).toBe('Adam started over.');
    expect(operationNote({ ...envelope, kind: 'startOver', keepLockedWords: true } as Operation, null)).toBe('A builder started over.');
    expect(operationNote({ ...envelope, kind: 'title', title: 'x' } as Operation, jay)).toBeNull();
    expect(operationNote({ ...envelope, kind: 'cells', writes: [{ col: 0, row: 0, value: 'A' }] } as Operation, jay)).toBeNull();
  });
});

describe('24-S7-3 the panel’s times and days', () => {
  it('24-hour HH:MM in local time; the day as "Nov 8, 2026"', () => {
    expect(formatNoteTime(new Date(2026, 10, 8, 9, 5))).toBe('09:05');
    expect(formatNoteTime(new Date(2026, 10, 8, 22, 41))).toBe('22:41');
    expect(formatNoteTime(new Date(2026, 10, 8, 0, 0))).toBe('00:00');
    expect(formatNoteDay(new Date(2026, 10, 8, 10, 17))).toBe('Nov 8, 2026');
    expect(formatNoteDay(new Date(2027, 0, 31, 23, 59))).toBe('Jan 31, 2027');
  });
});
